import raw from '../data/timeline.json';
import facesRaw from '../data/faces.json';

// timeline.json is generated by tools/plan_edit.py: the cut, the musical grid, word anchors.
export type PieceKind = 'lead' | 'speech' | 'gap' | 'tail';
export type Piece = {
  kind: PieceKind;
  srcIn: number; // seconds in media/source.mp4
  srcOut: number;
  from: number; // output frame
  durationInFrames: number;
  label?: string;
  onsetFrame?: number;
};
export type HfrClip = {file: string; startSec: number; endSec: number; fps: number};

type Timeline = {
  fps: number;
  width: number;
  height: number;
  bpm: number;
  beatFrames: number;
  beat0Frame: number;
  barPhase: number;
  durationInFrames: number;
  endCardFrame: number;
  pieces: Piece[];
  words: Record<string, number>;
  hfr: HfrClip[];
};

export const TL = raw as unknown as Timeline;
export const FPS = TL.fps;

/** Output frame of a key word (first syllable), e.g. W.ashyq. */
export const W = TL.words as Record<
  | 'dostar' | 'bizdin' | 'zhanaozen' | 'rovno' | 'bir_zhyl' | 'sogan' | 'kense' | 'klient'
  | 'ashyq' | 'habarlaimyz' | 'zhiyrma' | 'qarasha' | 'sagat' | 'on_bes' | 'nol_nolde'
  | 'keliniz' | 'sizderdi' | 'tosyn' | 'kutedi' | 'last_voice',
  number
>;

/** Output frame of musical beat b (beat 0 = "Достар!", 15 frames per beat at 120 BPM). */
export const beat = (b: number) => TL.beat0Frame + b * TL.beatFrames;

// ---- face track (tools/face_track.py), indexed by source frame, smoothed
type Faces = {fps: number; cx: number[]; cy: number[]; top: number[]; chin: number[]};
const FACES = facesRaw as unknown as Faces;

const sampleTrack = (arr: number[], srcSec: number) => {
  const x = Math.max(0, Math.min(arr.length - 1, srcSec * FACES.fps));
  const i = Math.floor(x);
  const j = Math.min(arr.length - 1, i + 1);
  return arr[i] + (arr[j] - arr[i]) * (x - i);
};

export const faceAt = (srcSec: number) => ({
  cx: sampleTrack(FACES.cx, srcSec),
  cy: sampleTrack(FACES.cy, srcSec),
  top: sampleTrack(FACES.top, srcSec),
  chin: sampleTrack(FACES.chin, srcSec),
});
